MOD = 998244353

def count_polish_sequences(n: int, a: list[int]) -> int:
    """Count Polish sequences of length n lexicographically <= a, modulo 998244353.

    Polish sequences are preorder degree encodings of rooted ordered trees.
    """
    limit = 2 * n
    fact = [1] * (limit + 1)
    for i in range(1, limit + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (limit + 1)
    inv_fact[limit] = pow(fact[limit], MOD - 2, MOD)
    for i in range(limit, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def choose(top: int, bottom: int) -> int:
        if bottom < 0 or bottom > top:
            return 0
        return fact[top] * inv_fact[bottom] % MOD * inv_fact[top - bottom] % MOD

    # Number of forests with r nodes and t roots. For r > 0 this is
    # t/r * C(2r-t-1, r-t), with zero outside 1 <= t <= r.
    def forests(r: int, t: int) -> int:
        if r == 0:
            return int(t == 0)
        if t < 1 or t > r:
            return 0
        return t * pow(r, MOD - 2, MOD) % MOD * choose(2 * r - t - 1, r - t) % MOD

    answer = 0
    slots = 1
    for i, bound in enumerate(a):
        remaining = n - i - 1
        if remaining == 0:
            # The final item must consume the last open child slot.
            target = 1 - slots
            if 0 <= target < bound:
                answer += 1
            if bound == target:
                answer += 1
            return answer % MOD

        # Try each smaller value at this position and count all valid suffix forests.
        lo = max(0, 2 - slots)  # ensures t = slots + x - 1 >= 1
        hi = min(bound - 1, remaining - slots + 1)  # ensures t <= remaining
        for x in range(lo, hi + 1):
            answer += forests(remaining, slots + x - 1)
        answer %= MOD

        slots += bound - 1
        if slots <= 0 or slots > remaining:
            return answer

    return answer % MOD

from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether available rectangular tiles can exactly cover the grid."""
    if n != len(tiles):
        n = min(n, len(tiles))
    area = h * w
    if sum(a * b for a, b in tiles[:n]) < area:
        return False

    # The grid is represented by one bit per cell.
    full = (1 << area) - 1
    placements = []
    for a, b in tiles[:n]:
        options = set()
        for height, width in {(a, b), (b, a)}:
            if height <= h and width <= w:
                for row in range(h - height + 1):
                    for col in range(w - width + 1):
                        bits = 0
                        row_bits = (1 << width) - 1
                        for rr in range(row, row + height):
                            bits |= row_bits << (rr * w + col)
                        options.add((height, width, row, col, bits))
        placements.append(options)

    tile_areas = [a * b for a, b in tiles[:n]]

    @lru_cache(None)
    def search(occupied: int, used: int) -> bool:
        if occupied == full:
            return True
        remaining = area - occupied.bit_count()
        if sum(tile_areas[i] for i in range(n) if not (used >> i) & 1) < remaining:
            return False

        # The first uncovered cell must be the top-left cell of the tile that
        # covers it: any cell above or to its left has already been filled.
        missing = full ^ occupied
        first = (missing & -missing).bit_length() - 1
        row, col = divmod(first, w)

        tried = set()
        for i in range(n):
            if (used >> i) & 1:
                continue
            shape = tuple(sorted(tiles[i]))
            if shape in tried:
                continue
            tried.add(shape)
            for height, width, r, c, bits in placements[i]:
                if r == row and c == col and not (bits & occupied):
                    if search(occupied | bits, used | (1 << i)):
                        return True
        return False

    return search(0, 0)

