def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper 3-colorings of the grid consistent with its fixed cells."""
    MOD = 998244353

    # Use the smaller side as the transfer direction's profile width.
    if W > H:
        grid = ["".join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    # Enumerate horizontally proper row patterns that also match fixed cells.
    allowed_rows = []
    for row in grid:
        patterns = []

        def build(col, prev, values):
            if col == W:
                patterns.append((tuple(values), tuple(
                    sum(1 << i for i, v in enumerate(values) if v == color)
                    for color in range(3)
                )))
                return
            ch = row[col]
            colors = range(3) if ch == '?' else (ord(ch) - ord('1'),)
            for color in colors:
                if color < 0 or color >= 3 or color == prev:
                    continue
                values.append(color)
                build(col + 1, color, values)
                values.pop()

        build(0, -1, [])
        if not patterns:
            return 0
        allowed_rows.append(patterns)

    dp = [1] * len(allowed_rows[0])
    for r in range(1, H):
        prev_patterns = allowed_rows[r - 1]
        curr_patterns = allowed_rows[r]
        next_dp = [0] * len(curr_patterns)
        # Encode each pattern as per-color bitmasks. Two rows are compatible
        # exactly when no column has the same color in both rows.
        prev_masks = [p[1] for p in prev_patterns]
        for j, (_, masks) in enumerate(curr_patterns):
            total = 0
            for i, old_masks in enumerate(prev_masks):
                if (masks[0] & old_masks[0]) == 0 and (masks[1] & old_masks[1]) == 0 and (masks[2] & old_masks[2]) == 0:
                    total += dp[i]
            next_dp[j] = total % MOD
        dp = next_dp
    return sum(dp) % MOD

