MOD = 998244353


def sum_of_scores(n: int, m: int) -> int:
    """Calculate the sum of divisor counts over all sequences of lengths 1..n."""
    # A product's divisor count is the product, over primes p, of
    # (1 + the total p-adic valuation across all sequence elements).
    primes = []
    for value in range(2, m + 1):
        is_prime = True
        for p in primes:
            if p * p > value:
                break
            if value % p == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(value)

    q = len(primes)
    count = q + 1
    dim = 2 * count

    # t_j(k)=binom(k,j)m^k and F_j(k)=sum_{i=0}^k t_j(i).
    # A single matrix transition advances k and adds the new term to F.
    mat = [[0] * dim for _ in range(dim)]
    for j in range(count):
        mat[j][j] = m
        if j:
            mat[j][j - 1] = m
        mat[count + j][count + j] = 1
        mat[count + j][j] = m
        if j:
            mat[count + j][j - 1] = m

    def mat_mul(a, b):
        out = [[0] * dim for _ in range(dim)]
        for i in range(dim):
            for k in range(dim):
                v = a[i][k]
                if v:
                    row = out[i]
                    bk = b[k]
                    for j in range(dim):
                        if bk[j]:
                            row[j] = (row[j] + v * bk[j]) % MOD
        return out

    def mat_vec(a, v):
        return [sum(a[i][j] * v[j] for j in range(dim)) % MOD
                for i in range(dim)]

    power = n
    vec = [0] * dim
    vec[0] = vec[count] = 1  # k=0 term included in F.
    base = mat
    while power:
        if power & 1:
            vec = mat_vec(base, vec)
        base = mat_mul(base, base)
        power >>= 1
    prefix = vec[count:]

    factorial = [1] * count
    for i in range(1, count):
        factorial[i] = factorial[i - 1] * i % MOD
    inv_m = pow(m, MOD - 2, MOD)
    weighted_lengths = []
    inv_power = 1
    for b in range(count):
        value = factorial[b] * prefix[b] % MOD * inv_power % MOD
        if b == 0:
            value = (value - 1) % MOD
        weighted_lengths.append(value)
        inv_power = inv_power * inv_m % MOD

