from typing import List


MOD = 998244353


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    """Given a lowercase English string s of length n and integer m,
    count length-m lowercase strings by their LCS length with s.
    """
    # A DP state is the LCS row for all prefixes of s after reading the
    # current prefix of the generated string. There are at most 2**n such
    # rows: adjacent entries can differ only by zero or one.
    chars = set(s)
    other_count = 26 - len(chars)
    other_char = next((chr(c) for c in range(ord("a"), ord("z") + 1)
                       if chr(c) not in chars), None)

    dp = {(0,) * (n + 1): 1}
    for _ in range(m):
        nxt = {}
        for row, ways in dp.items():
            # Characters appearing in s each have their own transition.
            for ch in chars:
                updated = [0] * (n + 1)
                for i in range(1, n + 1):
                    updated[i] = max(
                        row[i],
                        updated[i - 1],
                        row[i - 1] + (s[i - 1] == ch),
                    )
                state = tuple(updated)
                nxt[state] = (nxt.get(state, 0) + ways) % MOD

            # Every alphabet character absent from s induces the same row.
            if other_count:
                updated = [0] * (n + 1)
                for i in range(1, n + 1):
                    updated[i] = max(row[i], updated[i - 1])
                state = tuple(updated)
                nxt[state] = (nxt.get(state, 0) + ways * other_count) % MOD
        dp = nxt

    ans = [0] * (n + 1)
    for row, ways in dp.items():
        ans[row[n]] = (ans[row[n]] + ways) % MOD
    return ans

MOD = 998244353


def sum_of_scores(n: int, m: int) -> int:
    """Calculate the sum of divisor counts over all sequences of lengths 1..n."""
    primes = []
    for value in range(2, m + 1):
        is_prime = True
        for p in primes:
            if p * p > value:
                break
            if value % p == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(value)

    q = len(primes)
    count = q + 1
    dim = 2 * count

    # t_j(k)=binom(k,j)m^k and F_j(k)=sum_{i=0}^k t_j(i).
    # Advance k by one with t'_j=m(t_j+t_{j-1}) and F'_j=F_j+t'_j.
    mat = [[0] * dim for _ in range(dim)]
    for j in range(count):
        mat[j][j] = m
        if j:
            mat[j][j - 1] = m
        mat[count + j][count + j] = 1
        mat[count + j][j] = m
        if j:
            mat[count + j][j - 1] = m

    def mat_mul(a, b):
        out = [[0] * dim for _ in range(dim)]
        for i in range(dim):
            for k in range(dim):
                v = a[i][k]
                if v:
                    row = out[i]
                    bk = b[k]
                    for j in range(dim):
                        if bk[j]:
                            row[j] = (row[j] + v * bk[j]) % MOD
        return out

    def mat_vec(a, v):
        return [sum(a[i][j] * v[j] for j in range(dim)) % MOD
                for i in range(dim)]

    vec = [0] * dim
    vec[0] = vec[count] = 1
    base = mat
    power = n
    while power:
        if power & 1:
            vec = mat_vec(base, vec)
        base = mat_mul(base, base)
        power >>= 1
    prefix = vec[count:]

    factorial = [1] * count
    for i in range(1, count):
        factorial[i] = factorial[i - 1] * i % MOD
    inv_m = pow(m, MOD - 2, MOD)
    weighted_lengths = []
    inv_power = 1
    for b in range(count):
        value = factorial[b] * prefix[b] % MOD * inv_power % MOD
        if b == 0:
            value = (value - 1) % MOD
        weighted_lengths.append(value)
        inv_power = inv_power * inv_m % MOD

    moments = [0] * (1 << q)
    for mask in range(1 << q):
        total = 0
        for a in range(1, m + 1):
            term = 1
            for i, prime in enumerate(primes):
                if mask >> i & 1:
                    exponent = 0
                    t = a
                    while t % prime == 0:
                        exponent += 1
                        t //= prime
                    term *= exponent
            total += term
        moments[mask] = total % MOD

    coefficients = [0] * count

    def visit(remaining, blocks, product):
        if not remaining:
            coefficients[blocks] = (coefficients[blocks] + product) % MOD
            return
        bit = remaining & -remaining
        rest = remaining ^ bit
        sub = rest
        while True:
            block = sub | bit
            visit(remaining ^ block, blocks + 1,
                  product * moments[block] % MOD)
            if sub == 0:
                break
            sub = (sub - 1) & rest

    # Any subset of primes may contribute a nonconstant factor; primes outside
    # it contribute their 1 term in the divisor-count expansion.
    for mask in range(1 << q):
        visit(mask, 0, 1)
    return sum(coefficients[b] * weighted_lengths[b] for b in range(count)) % MOD

