from functools import lru_cache
from typing import List, Tuple


def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Takahashi and Aoki play optimally. A turn consists of playing a hand card and optionally taking one smaller table card. The player unable to move loses."""
    first = tuple(sorted(takahashi_cards))
    second = tuple(sorted(aoki_cards))
    table = tuple(sorted(table_cards))

    @lru_cache(maxsize=None)
    def winning(hand1: Tuple[int, ...], hand2: Tuple[int, ...], board: Tuple[int, ...], turn: int) -> bool:
        hand = hand1 if turn == 0 else hand2
        if not hand:
            return True
        for x in set(hand):
            remaining = list(hand)
            remaining.remove(x)
            new_board = tuple(sorted(board + (x,)))
            if turn == 0:
                if not winning(tuple(remaining), hand2, new_board, 1):
                    return True
            else:
                if not winning(hand1, tuple(remaining), new_board, 0):
                    return True
            for y in set(board):
                if y >= x:
                    continue
                captured = tuple(sorted(remaining + [y]))
                captured_board = list(board)
                captured_board.remove(y)
                captured_board.append(x)
                new_board2 = tuple(sorted(captured_board))
                if turn == 0:
                    if not winning(captured, hand2, new_board2, 1):
                        return True
                else:
                    if not winning(hand1, captured, new_board2, 0):
                        return True
        return False

    return "Takahashi" if winning(first, second, table, 0) else "Aoki"

