from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are placed according to these rules:
    - For integer triple (i, j, k) with 0 <= k < K:
      - If i and j have same parity: tile covers iK <= x <= (i+1)K and jK+k <= y <= jK+k+1
      - If i and j have different parity: tile covers iK+k <= x <= iK+k+1 and jK <= y <= (j+1)K

    Two tiles are adjacent if their edges share a positive-length segment.
    """
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K
    sk, tk = (S_y % K if (si + sj) % 2 == 0 else S_x % K), (
        T_y % K if (ti + tj) % 2 == 0 else T_x % K
    )

    if (si, sj, sk) == (ti, tj, tk):
        return 0

    # For very distant blocks, each crossed block boundary costs one move.
    # The checkerboard layout allows a monotone route to realize this bound;
    # endpoint strip choices only affect bounded local routes.
    coarse = abs(ti - si) + abs(tj - sj)
    if coarse > 100:
        return coarse

    # A block contains a path of K parallel tiles. Only endpoint indexes and
    # the two boundary indexes can affect a shortest path, so retain those
    # representatives even when K is enormous.
    indexes = sorted({0, K - 1, sk, tk})
    index_set = set(indexes)

    def is_h(i, j):
        return (i + j) % 2 == 0

    # Dijkstra over the finite set of blocks surrounding the endpoints.
    # Index changes within a block follow the path of parallel tiles.
    margin = 2
    imin, imax = min(si, ti) - margin, max(si, ti) + margin
    jmin, jmax = min(sj, tj) - margin, max(sj, tj) + margin

    start = (si, sj, sk)
    target = (ti, tj, tk)
    dist = {start: 0}
    heap = [(0, start)]

    while heap:
        d, node = heappop(heap)
        if d != dist[node]:
            continue
        if node == target:
            return d
        i, j, k = node

        def relax(other, cost):
            nd = d + cost
            if nd < dist.get(other, 10**100):
                dist[other] = nd
                heappush(heap, (nd, other))

        # Move between parallel tiles inside this block.
        for q in indexes:
            if q != k:
                relax((i, j, q), abs(q - k))

        if is_h(i, j):
            # H tiles span the block horizontally. Crossing a vertical block
            # edge reaches the boundary V strip; crossing a horizontal edge
            # is possible from the edge row and can reach any V strip.
            for di, dest_k in ((1, 0), (-1, K - 1)):
                ni = i + di
                if imin <= ni <= imax:
                    relax((ni, j, dest_k), 1)
            if k == 0 and j - 1 >= jmin:
                for q in indexes:
                    relax((i, j - 1, q), 1)
            if k == K - 1 and j + 1 <= jmax:
                for q in indexes:
                    relax((i, j + 1, q), 1)
        else:
            # V tiles span the block vertically. Crossing horizontal block
            # edges reaches a boundary H row; vertical strips can cross left
            # or right only when they lie at that block edge.
            for dj, dest_k in ((1, 0), (-1, K - 1)):
                nj = j + dj
                if jmin <= nj <= jmax:
                    relax((i, nj, dest_k), 1)
            if k == 0 and i - 1 >= imin:
                for q in indexes:
                    relax((i - 1, j, q), 1)
            if k == K - 1 and i + 1 <= imax:
                for q in indexes:
                    relax((i + 1, j, q), 1)

    return coarse

