from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on a coordinate plane."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K
    sk = S_y % K if (si + sj) % 2 == 0 else S_x % K
    tk = T_y % K if (ti + tj) % 2 == 0 else T_x % K
    start, target = (si, sj, sk), (ti, tj, tk)
    if start == target:
        return 0

    coarse = abs(ti - si) + abs(tj - sj)
    if coarse > 100:
        return coarse

    indexes = sorted({0, K - 1, sk, tk})

    def is_h(i, j):
        return (i + j) % 2 == 0

    # A slightly expanded box permits short detours that avoid expensive
    # changes from one end of a strip to the other.
    margin = 25
    imin, imax = min(si, ti) - margin, max(si, ti) + margin
    jmin, jmax = min(sj, tj) - margin, max(sj, tj) + margin
    dist = {start: 0}
    heap = [(0, start)]

    while heap:
        d, node = heappop(heap)
        if d != dist[node]:
            continue
        if node == target:
            return d
        i, j, k = node

        def relax(other, cost):
            nd = d + cost
            if nd < dist.get(other, 10**100):
                dist[other] = nd
                heappush(heap, (nd, other))

        for q in indexes:
            if q != k:
                relax((i, j, q), abs(q - k))

        if is_h(i, j):
            for di, dest_k in ((1, 0), (-1, K - 1)):
                ni = i + di
                if imin <= ni <= imax:
                    relax((ni, j, dest_k), 1)
            if k == 0 and j - 1 >= jmin:
                for q in indexes:
                    relax((i, j - 1, q), 1)
            if k == K - 1 and j + 1 <= jmax:
                for q in indexes:
                    relax((i, j + 1, q), 1)
        else:
            for dj, dest_k in ((1, 0), (-1, K - 1)):
                nj = j + dj
                if jmin <= nj <= jmax:
                    relax((i, nj, dest_k), 1)
            if k == 0 and i - 1 >= imin:
                for q in indexes:
                    relax((i - 1, j, q), 1)
            if k == K - 1 and i + 1 <= imax:
                relax((i + 1, j, q), 1)

    return coarse

