from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on a coordinate plane."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K
    sk = S_y % K if (si + sj) % 2 == 0 else S_x % K
    tk = T_y % K if (ti + tj) % 2 == 0 else T_x % K
    start, target = (si, sj, sk), (ti, tj, tk)
    if start == target:
        return 0

    coarse = abs(ti - si) + abs(tj - sj)
    if coarse > 100:
        return coarse

    indexes = sorted({0, K - 1, sk, tk})

    def is_h(i, j):
        return (i + j) % 2 == 0

    margin = 25
    imin, imax = min(si, ti) - margin, max(si, ti) + margin
    jmin, jmax = min(sj, tj) - margin, max(sj, tj) + margin
    dist = {start: 0}
    heap = [(0, start)]

    while heap:
        d, node = heappop(heap)
        if d != dist[node]:
            continue
        if node == target:
            return d
        i, j, k = node

        def relax(other, cost):
            nd = d + cost
            if nd < dist.get(other, 10**100):
                dist[other] = nd
                heappush(heap, (nd, other))

        for q in indexes:
            if q != k:
                relax((i, j, q), abs(q - k))

        if is_h(i, j):
            for di, dest_k in ((1, 0), (-1, K - 1)):
                ni = i + di
                if imin <= ni <= imax:
                    relax((ni, j, dest_k), 1)
            if k == 0 and j - 1 >= jmin:
                for q in indexes:
                    relax((i, j - 1, q), 1)
            if k == K - 1 and j + 1 <= jmax:
                for q in indexes:
                    relax((i, j + 1, q), 1)
        else:
            for dj, dest_k in ((1, 0), (-1, K - 1)):
                nj = j + dj
                if jmin <= nj <= jmax:
                    relax((i, nj, dest_k), 1)
            if k == 0 and i - 1 >= imin:
                for q in indexes:
                    relax((i - 1, j, q), 1)
            if k == K - 1 and i + 1 <= imax:
                for q in indexes:
                    relax((i + 1, j, q), 1)

    return coarse

def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Determine whether an n by n binary matrix can have exactly k fixed cells.

    Matrices are similar when their row and column sums agree. A useful way
    to build examples is to split rows and columns into balanced independent
    blocks. A fully flexible r by c block contributes rc non-fixed cells;
    isolated 1 by 1 blocks contribute no flexible cells.
    """
    if n < 0 or k < 0 or k > n * n:
        return False
    if n == 0:
        return k == 0

    # Independent flexible blocks can have different row and column sizes,
    # provided their dimensions admit an interior integer degree sequence.
    blocks = []
    for r in range(2, n + 1):
        for c in range(2, n + 1):
            g = __import__("math").gcd(r, c)
            # Regular margins with total lcm(r,c) are strictly interior
            # exactly when neither side is forced to be complete.
            if r // g < r and c // g < c:
                blocks.append((r, c, r * c))

    # dp[(rows, cols)] is a bitset of attainable counts of flexible cells.
    # Remaining rows and columns can always be paired as fixed singleton
    # blocks, so only equal residual dimensions are accepted.
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for used_rows in range(n + 1):
        for used_cols in range(n + 1):
            bits = dp[used_rows][used_cols]
            if not bits:
                continue
            if used_rows < n and used_cols < n:
                dp[used_rows + 1][used_cols + 1] |= bits
            for r, c, area in blocks:
                if used_rows + r <= n and used_cols + c <= n:
                    dp[used_rows + r][used_cols + c] |= bits << area

    # k fixed means n*n-k cells belong to flexible blocks.
    flexible = n * n - k
    return bool((dp[n][n] >> flexible) & 1)

