def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the area of black-painted regions in the wallpaper.

    The pattern repeats every 2 units horizontally and 4 units vertically.
    Integer-coordinate unit cells have contribution 0, 1, or 2 to twice
    the black area, according to the parity of their diagonal band.
    """
    # Sum the periodic unit-cell contributions with a 2D prefix function.
    # A unit cell whose lower-left coordinate sum is odd is cut in half by
    # a diagonal, and therefore contributes one to twice-area.
    def prefix(x: int, y: int) -> int:
        # Prefix over the integer lattice, decomposed into groups of four
        # diagonal bands. The even bands alternate black and white.
        qx, rx = divmod(x, 4)
        qy, ry = divmod(y, 4)
        total = 0
        # A 4 by 4 tile contains 8 area units of black.
        total += qx * qy * 8
        for i in range(rx):
            for j in range(4):
                total += cell(i, qy * 4 + j)
        for j in range(ry):
            for i in range(4):
                total += cell(qx * 4 + i, j)
        for i in range(rx):
            for j in range(ry):
                total += cell(i, j)
        return total

    def cell(i: int, j: int) -> int:
        s = i + j
        if s % 2:
            return 1
        return 2 if (s // 2) % 2 == 0 else 0

    return prefix(C, D) - prefix(A, D) - prefix(C, B) + prefix(A, B)

