from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine if available rectangular tiles can exactly cover an h-by-w grid."""
    if h <= 0 or w <= 0 or n < 0 or n > len(tiles):
        return False

    target = h * w
    areas = [a * b for a, b in tiles[:n]]
    subsets = []
    for chosen in range(1 << n):
        if sum(areas[i] for i in range(n) if chosen & (1 << i)) == target:
            subsets.append(chosen)
    if not subsets:
        return False

    full = (1 << target) - 1
    placement_cache = {}

    def placement_masks(a, b, pos):
        key = (a, b, pos)
        cached = placement_cache.get(key)
        if cached is not None:
            return cached
        row, col = divmod(pos, w)
        if row + a > h or col + b > w:
            result = ()
        else:
            row_bits = ((1 << b) - 1) << col
            result = tuple(row_bits << ((row + dr) * w) for dr in range(a))
            # Combine rows into one mask. The tuple above stores row masks.
            combined = 0
            for bits in result:
                combined |= bits
            result = (combined,)
        placement_cache[key] = result
        return result

    for selected in subsets:
        @lru_cache(maxsize=None)
        def search(occupied, used):
            if occupied == full:
                return True

            remaining = selected & ~used
            if not remaining:
                return False
            pos = next(i for i in range(target) if not (occupied >> i) & 1)

            while remaining:
                bit = remaining & -remaining
                idx = bit.bit_length() - 1
                remaining -= bit
                a, b = tiles[idx]
                orientations = {(a, b), (b, a)}
                for height, width in orientations:
                    if height * width > target - occupied.bit_count():
                        continue
                    masks = placement_masks(height, width, pos)
                    if masks:
                        mask = masks[0]
                        if not (occupied & mask) and search(occupied | mask, used | bit):
                            return True
            return False

        if search(0, 0):
            return True
    return False

