from functools import lru_cache


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count positive integers in [l, r] whose digit product is divisible by digit sum."""
    def count_up_to(n: int) -> int:
        if n <= 0:
            return 0
        digits = tuple(map(int, str(n)))
        width = len(digits)
        total = 0

        # The digit sum is at most 9 * width. For each possible sum, track
        # the product modulo that sum. Leading zeroes are padding and do not
        # participate in the product; zeroes within the number do.
        for target in range(1, 9 * width + 1):
            @lru_cache(maxsize=None)
            def visit(pos: int, remaining: int, product_mod: int,
                      started: bool, tight: bool) -> int:
                if remaining < 0 or remaining > 9 * (width - pos):
                    return 0
                if pos == width:
                    return int(started and remaining == 0 and product_mod == 0)

                limit = digits[pos] if tight else 9
                ways = 0
                for digit in range(limit + 1):
                    next_tight = tight and digit == limit
                    if not started and digit == 0:
                        ways += visit(pos + 1, remaining, product_mod, False, next_tight)
                    else:
                        next_product = (product_mod * digit) % target
                        ways += visit(pos + 1, remaining - digit, next_product, True, next_tight)
                return ways

            total += visit(0, target, 1 % target, False, True)
        return total

    return count_up_to(r) - count_up_to(l - 1)

MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N words containing every length-M word except X as a subsequence."""
    # Inclusion-exclusion on the words that are required to occur.  For a chosen
    # collection of words, count strings avoiding all of them with a subsequence
    # automaton whose state is the set of prefixes currently matched.
    words = [tuple((v for v in range(1, K + 1))) for _ in ()]  # typed empty initializer
    target = tuple(X)
    all_words = []
    def gen(prefix):
        if len(prefix) == M:
            if prefix != target:
                all_words.append(prefix)
            return
        for a in range(1, K + 1):
            gen(prefix + (a,))
    gen(())
    p = len(all_words)

    # The general inclusion-exclusion formulation.  Automaton states are the
    # longest matched prefix length for each forbidden word; equivalent states
    # are merged by the DP.
    from itertools import combinations
    def avoid_count(chosen):
        # Subsequence matching progress for each chosen word.
        pats = [all_words[i] for i in chosen]
        states = {(0,) * len(pats): 1}
        for _ in range(N):
            nxt = {}
            for state, ways in states.items():
                for a in range(1, K + 1):
                    ns = []
                    rejected = False
                    for j, pat in enumerate(pats):
                        q = state[j]
                        if q < M and pat[q] == a:
                            q += 1
                        if q == M:
                            rejected = True
                            break
                        ns.append(q)
                    if not rejected:
                        key = tuple(ns)
                        nxt[key] = (nxt.get(key, 0) + ways) % MOD
            states = nxt
        return sum(states.values()) % MOD

    # Avoid enumerating all subsets when a basic length bound proves the
    # requested coverage impossible.
    if K ** M - 1 > N * (N - 1) // 2 and M == 2:
        return 0
    ans = 0
    # Exact inclusion-exclusion. This is practical when the pattern universe is
    # small; larger instances retain the same exact formulation.
    for r in range(p + 1):
        sign = -1 if r & 1 else 1
        for subset in combinations(range(p), r):
            ans = (ans + sign * avoid_count(subset)) % MOD
    return ans

