def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Determine whether an n by n binary matrix can have exactly k fixed cells.

    Orient each cell from its row to its column when it is 1, and from its
    column to its row when it is 0. A cell can change while preserving all
    margins exactly when its directed edge lies on a directed cycle. Thus
    variable cells form complete row/column rectangles on strongly connected
    components; singleton vertices account for all remaining fixed cells.
    """
    if n < 2 or k < 0 or k > n * n:
        return False

    flexible = n * n - k
    if flexible == 0:
        return True

    # Pack disjoint strongly connected r-by-c blocks. For every r,c >= 2,
    # there is a 0/1 orientation of K_(r,c) that is strongly connected.
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for used_rows in range(n + 1):
        for used_cols in range(n + 1):
            bits = dp[used_rows][used_cols]
            if not bits:
                continue
            for r in range(2, n - used_rows + 1):
                for c in range(2, n - used_cols + 1):
                    dp[used_rows + r][used_cols + c] |= bits << (r * c)

    return any((dp[r][c] >> flexible) & 1
               for r in range(n + 1) for c in range(n + 1))

def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N words whose only missing length-M subsequence is X."""
    from math import comb
    mod = 998244353
    xcode = 0
    for x in X:
        xcode = xcode * K + x - 1
    if comb(N, M) < K ** M - 1:
        return 0

    # Store the subsequence language by length as base-K bitsets. Prefixes
    # with the same language have identical possible continuations.
    dp = {(0,) * M: 1}
    full = (1 << (K ** M)) - 1
    xbit = 1 << xcode
    answer = 0
    for length in range(N):
        remaining = N - length - 1
        # At most this many new length-M words can use the remaining positions.
        new_capacity = comb(N, M) - comb(length + 1, M)
        ndp = {}
        for state, ways in dp.items():
            for a in range(K):
                levels = list(state)
                for r in range(M - 1, 0, -1):
                    bits = state[r - 1]
                    added = 0
                    while bits:
                        low = bits & -bits
                        code = low.bit_length() - 1
                        added |= 1 << (code * K + a)
                        bits -= low
                    levels[r] |= added
                levels[0] |= 1 << a
                newstate = tuple(levels)
                missing = full ^ newstate[M - 1]
                if missing == xbit:
                    answer = (answer + ways * pow(K - 1, remaining, mod)) % mod
                elif missing and missing.bit_count() <= new_capacity:
                    ndp[newstate] = (ndp.get(newstate, 0) + ways) % mod
        dp = ndp
        if not dp:
            break
    return answer

