MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N words containing every length-M word except X as a subsequence."""
    target = tuple(X)

    # Every constant word a^M must occur unless it is X, requiring M copies
    # of each corresponding symbol.
    required = K * M - (M if len(set(target)) == 1 and len(target) == M else 0)
    if N < required:
        return 0

    all_words = []

    def generate(prefix):
        if len(prefix) == M:
            if prefix != target:
                all_words.append(prefix)
            return
        for value in range(1, K + 1):
            generate(prefix + (value,))

    generate(())
    p = len(all_words)

    # For a selected set of required subsequences, count strings that avoid
    # every selected word. Greedy progress per pattern is sufficient because
    # subsequence matching has a unique earliest completion state.
    def avoid_count(selected):
        patterns = [all_words[i] for i in selected]
        states = {(0,) * len(patterns): 1}
        for _ in range(N):
            nxt = {}
            for state, ways in states.items():
                for value in range(1, K + 1):
                    progress = []
                    rejected = False
                    for j, pattern in enumerate(patterns):
                        q = state[j]
                        if pattern[q] == value:
                            q += 1
                        if q == M:
                            rejected = True
                            break
                        progress.append(q)
                    if not rejected:
                        key = tuple(progress)
                        nxt[key] = (nxt.get(key, 0) + ways) % MOD
            states = nxt
        return sum(states.values()) % MOD

    # Inclusion-exclusion over the patterns absent from a candidate string.
    # This is exponential in the number of length-M patterns, but exact.
    from itertools import combinations

    answer = 0
    for size in range(p + 1):
        sign = -1 if size & 1 else 1
        for selected in combinations(range(p), size):
            answer = (answer + sign * avoid_count(selected)) % MOD
    return answer

def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N words whose only missing length-M subsequence is X."""
    from math import comb
    mod = 998244353
    xcode = 0
    for x in X:
        xcode = xcode * K + x - 1
    if comb(N, M) < K ** M - 1:
        return 0

    # Store the subsequence language by length as base-K bitsets. Prefixes
    # with the same language have identical possible continuations.
    dp = {(0,) * M: 1}
    full = (1 << (K ** M)) - 1
    xbit = 1 << xcode
    answer = 0
    for length in range(N):
        remaining = N - length - 1
        new_capacity = comb(N, M) - comb(length + 1, M)
        ndp = {}
        for state, ways in dp.items():
            for a in range(K):
                levels = list(state)
                for r in range(M - 1, 0, -1):
                    bits = state[r - 1]
                    added = 0
                    while bits:
                        low = bits & -bits
                        code = low.bit_length() - 1
                        added |= 1 << (code * K + a)
                        bits -= low
                    levels[r] |= added
                levels[0] |= 1 << a
                newstate = tuple(levels)
                missing = full ^ newstate[M - 1]
                if missing == xbit:
                    answer = (answer + ways * pow(K - 1, remaining, mod)) % mod
                elif missing and (missing & ~xbit).bit_count() <= new_capacity:
                    ndp[newstate] = (ndp.get(newstate, 0) + ways) % mod
        dp = ndp
        if not dp:
            break
    return answer

def can_color_all_points(n: int, k: int) -> bool:
    """Return whether alternating reflection constraints allow all points to be colored.

    Reflection across the axis through point p maps point x to (2*p - x) mod n.
    A legal coloring step either completes the sole unmatched reflection pair
    for the active axis, or adds a fixed point when the colored set is already
    symmetric about that axis.
    """
    axes = (0, k)

    def fixed_points(p: int):
        if n % 2:
            return (p,)
        return (p, (p + n // 2) % n)

    # A one-point set can be symmetric about Alice's axis only at a fixed point.
    pending = []
    for first in fixed_points(0):
        black = bytearray(n)
        black[first] = 1
        unmatched = [set(), set()]
        for idx, p in enumerate(axes):
            mate = (2 * p - first) % n
            if mate != first and not black[mate]:
                unmatched[idx].add(first)
        pending.append((black, unmatched, 1))

    while pending:
        black, unmatched, count = pending.pop()
        while count < n:
            idx = count % 2
            p = axes[idx]
            open_pairs = unmatched[idx]

            if len(open_pairs) > 1:
                break
            if open_pairs:
                y = next(iter(open_pairs))
                choices = ((2 * p - y) % n,)
            else:
                choices = tuple(x for x in fixed_points(p) if not black[x])
                if not choices:
                    break

            if len(choices) > 1:
                for x in choices[1:]:
                    next_black = black.copy()
                    next_black[x] = 1
                    next_unmatched = [unmatched[0].copy(), unmatched[1].copy()]
                    for j, axis in enumerate(axes):
                        mate = (2 * axis - x) % n
                        if mate != x:
                            if next_black[mate]:
                                next_unmatched[j].discard(mate)
                            else:
                                next_unmatched[j].add(x)
                    pending.append((next_black, next_unmatched, count + 1))

            x = choices[0]
            black[x] = 1
            for j, axis in enumerate(axes):
                mate = (2 * axis - x) % n
                if mate != x:
                    if black[mate]:
                        unmatched[j].discard(mate)
                    else:
                        unmatched[j].add(x)
            count += 1

        if count == n:
            return True

    return False

