def count_good_sequences(N: int, M: int) -> int:
    """Count length-M sequences whose product is at most N and has sigma(n) divisible by 3.

    The number of sequences with product n is the M-fold divisor function:
    for each p**e exactly dividing n its factor is C(M+e-1, e).
    """
    mod = 998244353
    if N <= 1:
        return 0

    max_exp = N.bit_length()
    weights = [1] * (max_exp + 1)
    for e in range(1, max_exp + 1):
        weights[e] = weights[e - 1] * (M + e - 1) % mod
        weights[e] = weights[e] * pow(e, mod - 2, mod) % mod

    # For moderate bounds a smallest-prime-factor table gives a simple
    # linear-time summation over the multiplicative function.
    if N <= 1_000_000:
        spf = [0] * (N + 1)
        primes = []
        for x in range(2, N + 1):
            if not spf[x]:
                spf[x] = x
                primes.append(x)
            for p in primes:
                if p > spf[x] or p * x > N:
                    break
                spf[p * x] = p

        total = 0
        for n in range(2, N + 1):
            t = n
            w = 1
            good = False
            while t > 1:
                p = spf[t]
                e = 0
                while t % p == 0:
                    t //= p
                    e += 1
                w = w * weights[e] % mod
                if p == 3 or p % 3 == 1:
                    good |= (e + 1) % 3 == 0
                else:
                    good |= e % 2 == 1
            if good:
                total += w
        return total % mod

    # For larger bounds enumerate prime-power factorizations in increasing
    # prime order. This exact recurrence is useful for sparse/small instances.
    limit = int(N ** 0.5)
    sieve = bytearray(b"\x01") * (limit + 1)
    sieve[0:2] = b"\x00\x00"
    primes = []
    for p in range(2, limit + 1):
        if sieve[p]:
            primes.append(p)
            if p * p <= limit:
                sieve[p * p:limit + 1:p] = b"\x00" * (((limit - p * p) // p) + 1)

    total = 0

    def visit(start, remaining, weight, good):
        nonlocal total
        if good:
            total = (total + weight) % mod
        for i in range(start, len(primes)):
            p = primes[i]
            if p > remaining:
                break
            q = p
            e = 1
            while q <= remaining:
                local_good = ((e + 1) % 3 == 0) if p == 3 or p % 3 == 1 else (e % 2 == 1)
                visit(i + 1, remaining // q, weight * weights[e] % mod, good or local_good)
                if q > remaining // p:
                    break
                q *= p
                e += 1

    visit(0, N, 1, False)
    return total

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on the coordinate plane."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K
    same_parity = lambda i, j: (i - j) % 2 == 0
    start_k = (S_y % K) if same_parity(si, sj) else (S_x % K)
    target_k = (T_y % K) if same_parity(ti, tj) else (T_x % K)
    if (si, sj, start_k) == (ti, tj, target_k):
        return 0

    span = abs(ti - si) + abs(tj - sj)
    if span > 30:
        return span

    # Only endpoint indices and the two block-edge indices can be useful:
    # a long-side crossing can choose any strip, and can choose its next
    # useful edge or the target strip without extra cost.
    indices = sorted({0, K - 1, start_k, target_k})
    index_set = set(indices)
    from heapq import heappop, heappush

    # A small margin permits paths around a local corner while keeping the
    # search finite. States are (block x, block y, strip index).
    xmin, xmax = min(si, ti) - 2, max(si, ti) + 2
    ymin, ymax = min(sj, tj) - 2, max(sj, tj) + 2

    def add_if_inside(out, i, j, k, cost):
        if xmin <= i <= xmax and ymin <= j <= ymax and k in index_set:
            out.append(((i, j, k), cost))

    def neighbors(state):
        i, j, k = state
        out = []
        add_if_inside(out, i, j, k, 0)
        # Moving within one block follows its chain of K strips.
        for other in indices:
            if other != k:
                out.append(((i, j, other), abs(k - other) if same_parity(i, j) else abs(k - other)))
        if same_parity(i, j):  # horizontal tiles, strip index is local y
            add_if_inside(out, i - 1, j, K - 1, 1)
            add_if_inside(out, i + 1, j, 0, 1)
            if k == 0:
                for x in indices:
                    add_if_inside(out, i, j - 1, x, 1)
            if k == K - 1:
                for x in indices:
                    add_if_inside(out, i, j + 1, x, 1)
        else:  # vertical tiles, strip index is local x
            if k == 0:
                for y in indices:
                    add_if_inside(out, i - 1, j, y, 1)
            if k == K - 1:
                for y in indices:
                    add_if_inside(out, i + 1, j, y, 1)
            add_if_inside(out, i, j - 1, K - 1, 1)
            add_if_inside(out, i, j + 1, 0, 1)
        return out

    start = (si, sj, start_k)
    target = (ti, tj, target_k)
    distances = {start: 0}
    heap = [(0, start)]
    while heap:
        distance, state = heappop(heap)
        if distance != distances[state]:
            continue
        if state == target:
            return distance
        for nxt, cost in neighbors(state):
            candidate = distance + cost
            if candidate < distances.get(nxt, 10**100):
                distances[nxt] = candidate
                heappush(heap, (candidate, nxt))
    return span

