from math import comb

MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N words whose only missing length-M subsequence is X."""
    xcode = 0
    for value in X:
        xcode = xcode * K + value - 1
    xbit = 1 << xcode
    full = (1 << (K ** M)) - 1

    # Each level r is a bitset of the length-r words occurring as subsequences
    # so far, encoded in base K. Appending a symbol extends every existing
    # (r-1)-word by that symbol.
    dp = {(0,) * M: 1}
    for length in range(N):
        remaining = N - length - 1
        nxt = {}
        max_new = comb(N, M) - comb(length + 1, M)
        for state, ways in dp.items():
            for symbol in range(K):
                levels = list(state)
                for r in range(M - 1, 0, -1):
                    bits = state[r - 1]
                    extended = 0
                    while bits:
                        low = bits & -bits
                        code = low.bit_length() - 1
                        extended |= 1 << (code * K + symbol)
                        bits ^= low
                    levels[r] |= extended
                levels[0] |= 1 << symbol
                new_state = tuple(levels)
                missing = full ^ new_state[M - 1]
                if remaining == 0:
                    if missing != xbit:
                        continue
                elif (missing & ~xbit).bit_count() > max_new:
                    continue
                nxt[new_state] = (nxt.get(new_state, 0) + ways) % MOD
        dp = nxt
        if not dp:
            return 0
    return sum(dp.values()) % MOD

