def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N words whose only missing length-M subsequence is X."""
    target = tuple(X)
    # All constant words must occur, except the one constant word equal to X.
    missing_constant = len(set(target)) == 1 and len(target) == M
    if N < K * M - (M if missing_constant else 0):
        return 0

    xcode = 0
