def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on the coordinate plane."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K
    same_parity = lambda i, j: (i - j) % 2 == 0
    start_k = (S_y % K) if same_parity(si, sj) else (S_x % K)
    target_k = (T_y % K) if same_parity(ti, tj) else (T_x % K)
    if (si, sj, start_k) == (ti, tj, target_k):
        return 0

    span = abs(ti - si) + abs(tj - sj)
    if span > 30:
        return span

    # Only endpoint indices and the two block-edge indices can be useful:
    # a long-side crossing can choose any strip, and can choose its next
    # useful edge or the target strip without extra cost.
    indices = sorted({0, K - 1, start_k, target_k})
    index_set = set(indices)
    from heapq import heappop, heappush

    xmin, xmax = min(si, ti) - 2, max(si, ti) + 2
    ymin, ymax = min(sj, tj) - 2, max(sj, tj) + 2

    def add_if_inside(out, i, j, k, cost):
        if xmin <= i <= xmax and ymin <= j <= ymax and k in index_set:
            out.append(((i, j, k), cost))

    def neighbors(state):
        i, j, k = state
        out = []
        for other in indices:
            if other != k:
                out.append(((i, j, other), abs(k - other)))
        if same_parity(i, j):
            add_if_inside(out, i - 1, j, K - 1, 1)
            add_if_inside(out, i + 1, j, 0, 1)
            if k == 0:
                for x in indices:
                    add_if_inside(out, i, j - 1, x, 1)
            if k == K - 1:
                for x in indices:
                    add_if_inside(out, i, j + 1, x, 1)
        else:
            if k == 0:
                for y in indices:
                    add_if_inside(out, i - 1, j, y, 1)
            if k == K - 1:
                for y in indices:
                    add_if_inside(out, i + 1, j, y, 1)
            add_if_inside(out, i, j - 1, K - 1, 1)
            add_if_inside(out, i, j + 1, 0, 1)
        return out

    start = (si, sj, start_k)
    target = (ti, tj, target_k)
    distances = {start: 0}
    heap = [(0, start)]
    while heap:
        distance, state = heappop(heap)
        if distance != distances[state]:
            continue
        if state == target:
            return distance
        for nxt, cost in neighbors(state):
            candidate = distance + cost
            if candidate < distances.get(nxt, 10**100):
                distances[nxt] = candidate
                heappush(heap, (candidate, nxt))
    return span

