def count_good_sequences(N: int, M: int) -> int:
    """Count length-M sequences whose product is at most N and has sigma(n) divisible by 3."""
    mod = 998244353
    if N <= 1:
        return 0

    max_exp = N.bit_length()
    weights = [1] * (max_exp + 1)
    for e in range(1, max_exp + 1):
        weights[e] = weights[e - 1] * (M + e - 1) % mod
        weights[e] = weights[e] * pow(e, mod - 2, mod) % mod

    if N <= 1_000_000:
        spf = [0] * (N + 1)
        primes = []
        for x in range(2, N + 1):
            if not spf[x]:
                spf[x] = x
                primes.append(x)
            for p in primes:
                if p > spf[x] or p * x > N:
                    break
                spf[p * x] = p

        total = 0
        for n in range(2, N + 1):
            t = n
            w = 1
            good = False
            while t > 1:
                p = spf[t]
                e = 0
                while t % p == 0:
                    t //= p
                    e += 1
                w = w * weights[e] % mod
                if p != 3:
                    if p % 3 == 1:
                        good |= (e + 1) % 3 == 0
                    else:
                        good |= e % 2 == 1
            if good:
                total += w
        return total % mod

    # Enumerate prime-power factorizations in increasing prime order.
    limit = int(N ** 0.5)
    sieve = bytearray(b"\x01") * (limit + 1)
    sieve[0:2] = b"\x00\x00"
    primes = []
    for p in range(2, limit + 1):
        if sieve[p]:
            primes.append(p)
            if p * p <= limit:
                sieve[p * p:limit + 1:p] = b"\x00" * (((limit - p * p) // p) + 1)

    total = 0

    def visit(start, remaining, weight, good):
        nonlocal total
        if good:
            total = (total + weight) % mod
        for i in range(start, len(primes)):
            p = primes[i]
            if p > remaining:
                break
            q = p
            e = 1
            while q <= remaining:
                if p == 3:
                    local_good = False
                elif p % 3 == 1:
                    local_good = (e + 1) % 3 == 0
                else:
                    local_good = e % 2 == 1
                visit(i + 1, remaining // q, weight * weights[e] % mod, good or local_good)
                if q > remaining // p:
                    break
                q *= p
                e += 1

    visit(0, N, 1, False)
    return total

