def count_paths(W: int, H: int, L: int, R: int, D: int, U: int) -> int:
    """Count monotone unit-step paths through valid lattice points."""
    MOD = 998244353
    if (W + 1) * (H + 1) <= 3_000_000:
        prev = [0] * (W + 1)
        total = 0
        for y in range(H + 1):
            row = [0] * (W + 1)
            for x in range(W + 1):
                if L <= x <= R and D <= y <= U:
                    continue
                row[x] = (1 + prev[x] + (row[x - 1] if x else 0)) % MOD
                total += row[x]
            total %= MOD
            prev = row
        return total
    nmax = W + H + 5
    fact = [1] * (nmax + 1)
    for i in range(1, nmax + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact = [1] * (nmax + 1)
    invfact[nmax] = pow(fact[nmax], MOD - 2, MOD)
    for i in range(nmax, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD
    def c(n, k):
        if n < 0 or k < 0 or n < k:
            return 0
        return fact[n] * invfact[k] % MOD * invfact[n-k] % MOD
    def gsum(a, b):
        if a < 0 or b < 0:
            return 0
        return (c(a+b+4, b+2)-a-b-4) % MOD
    def fsum(a, b):
        if a < 0 or b < 0:
            return 0
        return (gsum(a,b)-(a+1)*(b+1)) % MOD
    def point(x, y):
        return (c(x+y+2, x+1)-1) % MOD
    def kernel(n, m):
        # Sum binom(d+v,d) for 0<=d<=n, 1<=v<=m.
        return (c(n+m+2, n+1)-(n+2)) % MOD
    h, k = U-D+1, H-U
    n = W-R-1
    answer = (gsum(W,D-1)-(W+1)*D) % MOD
    answer += fsum(L-1,U)-fsum(L-1,D-1)
    answer += fsum(n,h-1)
    for j in range(R+1, W+1):
        answer += point(j,D-1) * kernel(W-j,h)
    answer += fsum(W,k-1)
    left_boundary_sources = 0
    for x in range(L):
        value = point(x,U)
        left_boundary_sources += value
        answer += value * kernel(W-x,k)
    answer -= left_boundary_sources * kernel(W-L,k)
    answer += fsum(n,h+k-1)-fsum(n,h-1)-fsum(n,k-1)
    for j in range(R+1, W+1):
        answer += point(j,D-1) * (kernel(W-j,h+k)-kernel(W-j,h))
    return answer % MOD

def count_good_sequences(N: int, M: int) -> int:
    """ Count the number of length-M sequences of positive integers whose product is a "good integer" not exceeding N.

    A positive integer n is called a "good integer" if and only if the sum of its positive divisors is divisible by 3.

    The result should be returned modulo 998244353.

    Args:
        N: Upper bound for the product of elements in the sequence (1 <= N <= 10^10)
        M: Length of the sequences (1 <= M <= 10^5)

    Returns:
        The number of valid sequences modulo 998244353

    >>> count_good_sequences(10, 1)
    5
    >>> count_good_sequences(4, 2)
    2
    >>> count_good_sequences(370, 907)
    221764640
    """
    mod = 998244353
    if N <= 1:
        return 0

    max_exp = N.bit_length()
    weights = [1] * (max_exp + 1)
    for e in range(1, max_exp + 1):
        weights[e] = weights[e - 1] * (M + e - 1) % mod
        weights[e] = weights[e] * pow(e, mod - 2, mod) % mod

    if N <= 1_000_000:
        spf = [0] * (N + 1)
        primes = []
        for x in range(2, N + 1):
            if not spf[x]:
                spf[x] = x
                primes.append(x)
            for p in primes:
                if p > spf[x] or p * x > N:
                    break
                spf[p * x] = p

        total = 0
        for n in range(2, N + 1):
            t = n
            w = 1
            good = False
            while t > 1:
                p = spf[t]
                e = 0
                while t % p == 0:
                    t //= p
                    e += 1
                w = w * weights[e] % mod
                if p != 3:
                    if p % 3 == 1:
                        good |= (e + 1) % 3 == 0
                    else:
                        good |= e % 2 == 1
            if good:
                total += w
        return total % mod

    limit = int(N ** 0.5)
    sieve = bytearray(b"\x01") * (limit + 1)
    sieve[0:2] = b"\x00\x00"
    primes = []
    for p in range(2, limit + 1):
        if sieve[p]:
            primes.append(p)
            if p * p <= limit:
                sieve[p * p:limit + 1:p] = b"\x00" * (((limit - p * p) // p) + 1)

    total = 0

    def visit(start, remaining, weight, good):
        nonlocal total
        if good:
            total = (total + weight) % mod
        for i in range(start, len(primes)):
            p = primes[i]
            if p > remaining:
                break
            q = p
            e = 1
            while q <= remaining:
                if p == 3:
                    local_good = False
                elif p % 3 == 1:
                    local_good = (e + 1) % 3 == 0
                else:
                    local_good = e % 2 == 1
                visit(i + 1, remaining // q, weight * weights[e] % mod, good or local_good)
                if q > remaining // p:
                    break
                q *= p
                e += 1

    visit(0, N, 1, False)

    # Every remaining n has a unique factorization n=m*q with q prime > sqrt(N)
    # and m <= sqrt(N). Sum q by residue class after a segmented prime sieve.
    query_values = sorted({N // m for m in range(1, limit + 1) if N // m > limit})
    prime_prefix = {}
    query_index = 0
    count1 = count2 = 0
    block_size = 100_000
    lo = limit + 1
    while lo <= N:
        hi = min(N + 1, lo + block_size)
        flags = bytearray(b"\x01") * (hi - lo)
        for p in primes:
            if p * p >= hi:
                break
            first = max(p * p, ((lo + p - 1) // p) * p)
            if first < hi:
                flags[first - lo:hi - lo:p] = b"\x00" * (((hi - 1 - first) // p) + 1)
        for offset, prime_flag in enumerate(flags):
            value = lo + offset
            if prime_flag:
                if value % 3 == 1:
                    count1 += 1
                elif value % 3 == 2:
                    count2 += 1
            while query_index < len(query_values) and query_values[query_index] == value:
                prime_prefix[value] = (count1, count2)
                query_index += 1
        lo = hi

    small_spf = [0] * (limit + 1)
    small_primes = []
    for x in range(2, limit + 1):
        if not small_spf[x]:
            small_spf[x] = x
            small_primes.append(x)
        for p in small_primes:
            if p > small_spf[x] or p * x > limit:
                break
            small_spf[p * x] = p

    tail = 0
    for m in range(1, limit + 1):
        t = m
        w = 1
        good = False
        while t > 1:
            p = small_spf[t]
            e = 0
            while t % p == 0:
                t //= p
                e += 1
            w = w * weights[e] % mod
            if p != 3:
                if p % 3 == 1:
                    good |= (e + 1) % 3 == 0
                else:
                    good |= e % 2 == 1
        upper = N // m
        c1, c2 = prime_prefix.get(upper, (0, 0))
        tail += w * M * (c1 + c2 if good else c2)

    return (total + tail) % mod

